solution.typescript:
function twoSum(nums: number[], target: number): number[] {
    const seen = new Map<number, number>();      // 哈希表:值 -> 下标,记住"见过谁"
    for (let i = 0; i < nums.length; i++) {
        const need = target - nums[i];
        if (seen.has(need)) {                     // 搭档已经出现过 -> 配对成功
            return [seen.get(need)!, i];
        }
        seen.set(nums[i], i);                     // 没配上,把自己记下来供后面查
    }
    return [];
}

