solution.typescript:
function threeSum(nums: number[]): number[][] {
    // (a,b)=>a-b:靠差值正负决定升序，从小到大
    nums.sort((a, b) => a - b);                   // 排序,让双指针能靠大小移动
    const res: number[][] = [];
    const n = nums.length;
    for (let i = 0; i < n - 2; i++) {
        if (nums[i] > 0) break;                   // 最小的都 >0,三数和不可能为 0,提前收工
        if (i > 0 && nums[i] === nums[i - 1]) continue;   // 去重①:跳过重复的固定值
        let l = i + 1, r = n - 1;                 // 在 i 右侧的有序区间里对撞找两数
        while (l < r) {
            const s = nums[i] + nums[l] + nums[r];
            if (s < 0) l++;                       // 和偏小,左指针右移把和调大
            else if (s > 0) r--;                  // 和偏大,右指针左移把和调小
            else {
                res.push([nums[i], nums[l], nums[r]]);
                while (l < r && nums[l] === nums[l + 1]) l++;   // 去重②:左
                while (l < r && nums[r] === nums[r - 1]) r--;   // 去重③:右
                l++; r--;                         // 收完这组,两边同时向内跨一步
            }
        }
    }
    return res;
}

