function maxSubArray(nums: number[]): number {
    let cur = nums[0], best = nums[0];            // cur:以当前元素结尾的最大和;best:全局答案
    for (let i = 1; i < nums.length; i++) {
        cur = Math.max(nums[i], cur + nums[i]);   // 前面是负担就甩掉(取 x),否则接上
        best = Math.max(best, cur);               // 随时记录见过的最大值
    }
    return best;
}

