solution.typescript:
function merge(intervals: number[][]): number[][] {
    intervals.sort((a, b) => a[0] - b[0]);        // 按左端点排序,重叠只可能发生在相邻区间
    const res: number[][] = [intervals[0]];
    for (let i = 1; i < intervals.length; i++) {
        const [l, r] = intervals[i];
        const last = res[res.length - 1];
        if (l <= last[1]) {                       // 当前左端 <= 上一段右端 -> 有重叠
            last[1] = Math.max(last[1], r);       // 合并,右端取更大的
        } else {
            res.push([l, r]);                     // 不重叠,另起一段
        }
    }
    return res;
}

