function productExceptSelf(nums: number[]): number[] {
    const n = nums.length;
    const res = new Array(n).fill(1);
    for (let i = 1; i < n; i++) {
        res[i] = res[i - 1] * nums[i - 1];        // 第一遍:res[i] 存 i 左边所有数的乘积
    }
    let right = 1;                                // right 累积 i 右边所有数的乘积
    for (let i = n - 1; i >= 0; i--) {
        res[i] *= right;                          // 左积 × 右积 = 答案
        right *= nums[i];                         // 更新右积,带上当前数供左边的位置用
    }
    return res;
}

