function maxArea(height: number[]): number {
    let l = 0, r = height.length - 1;             // 两端起步,此时宽度最大
    let best = 0;
    while (l < r) {
        best = Math.max(best, (r - l) * Math.min(height[l], height[r]));  // 面积 = 宽 × 矮边
        if (height[l] < height[r]) l++;           // 移动矮的一侧,才有机会换更高的板
        else r--;
    }
    return best;
}

