function trap(height: number[]): number {
    let l = 0, r = height.length - 1;
    let lmax = 0, rmax = 0, water = 0;            // lmax/rmax:左右两侧目前见过的最高墙
    while (l < r) {
        if (height[l] < height[r]) {              // 左侧更矮 -> 左边是瓶颈,结算左格
            lmax = Math.max(lmax, height[l]);
            water += lmax - height[l];            // 当前格储水 = 左侧最高墙 - 自身高度
            l++;
        } else {                                  // 右侧更矮 -> 结算右格
            rmax = Math.max(rmax, height[r]);
            water += rmax - height[r];
            r--;
        }
    }
    return water;
}

