function moveZeroes(nums: number[]): void {
    let slow = 0;                                 // slow:下一个非零数该放的位置
    for (let fast = 0; fast < nums.length; fast++) {
        if (nums[fast] !== 0) {                   // 快指针遇到非零
            [nums[slow], nums[fast]] = [nums[fast], nums[slow]];  // 交换到前面的坑
            slow++;                               // 坑位后移
        }
    }
}

