solution.typescript:
function lengthOfLongestSubstring(s: string): number {
    const last = new Map<string, number>();       // 字符 -> 最近一次出现的下标
    let left = 0, best = 0;                        // left:窗口左边界
    for (let right = 0; right < s.length; right++) {
        const c = s[right];
        if (last.has(c) && last.get(c)! >= left) { // c 在当前窗口内重复了
            left = last.get(c)! + 1;               // 左边界直接跳到重复字符的下一位
        }
        last.set(c, right);                        // 更新 c 的最新位置
        best = Math.max(best, right - left + 1);   // 当前窗口长度刷新答案
    }
    return best;
}

