solution.typescript:
function findAnagrams(s: string, p: string): number[] {
    if (s.length < p.length) return [];
    const need = new Array(26).fill(0);           // 目标字符统计
    const win = new Array(26).fill(0);            // 当前窗口的字符统计
    const idx = (c: string) => c.charCodeAt(0) - 97;
    for (const c of p) need[idx(c)]++;
    const res: number[] = [];
    for (let i = 0; i < s.length; i++) {
        win[idx(s[i])]++;                         // 右边进一个新字符
        if (i >= p.length) win[idx(s[i - p.length])]--;   // 左边出一个旧字符
        if (i >= p.length - 1 && win.every((v, j) => v === need[j])) {   // 窗口统计 == 目标 -> 命中
            res.push(i - p.length + 1);
        }
    }
    return res;
}

