solution.typescript:
function minWindow(s: string, t: string): string {
    const need = new Map<string, number>();       // 还需要的字符计数(可为负,表示窗口内多余)
    for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);
    let missing = t.length;                       // 还差多少个字符才集齐
    let left = 0;
    let bestLen = Infinity, bs = 0, be = 0;        // 最短长度及其起止
    for (let right = 0; right < s.length; right++) {
        const c = s[right];
        if ((need.get(c) ?? 0) > 0) missing--;    // 这个 c 是真正需要的(不是多余)
        need.set(c, (need.get(c) ?? 0) - 1);      // 无论如何计数都要减(多余的会变负)
        while (missing === 0) {                   // 窗口已覆盖 t,尝试收缩左边界
            if (right - left < bestLen) { bestLen = right - left; bs = left; be = right; }
            const lc = s[left];
            need.set(lc, (need.get(lc) ?? 0) + 1); // 左字符移出窗口,归还计数
            if ((need.get(lc) ?? 0) > 0) missing++;// 归还后变正 -> 缺了一个必需字符
            left++;
        }
    }
    return bestLen === Infinity ? "" : s.slice(bs, be + 1);
}

