solution.typescript:
function longestPalindrome(s: string): string {
    let best = "";
    const expand = (l: number, r: number): string => {   // 从中心 (l, r) 向两边扩
        while (l >= 0 && r < s.length && s[l] === s[r]) { // 两边字符相同就继续扩
            l--; r++;
        }
        return s.slice(l + 1, r);                 // 跳出时多走了一步,故取 l+1 .. r-1
    };
    for (let i = 0; i < s.length; i++) {
        const odd = expand(i, i);                 // 奇数中心:单字符 i
        const even = expand(i, i + 1);            // 偶数中心:缝隙 i,i+1
        if (odd.length > best.length) best = odd;
        if (even.length > best.length) best = even;
    }
    return best;
}

