solution.typescript:
function isValid(s: string): boolean {
    const pairs: Record<string, string> = { ')': '(', ']': '[', '}': '{' };  // 右括号 -> 左括号
    const stack: string[] = [];
    for (const c of s) {
        if (c in pairs) {                         // 遇到右括号
            if (stack.pop() !== pairs[c]) return false;   // 栈空或栈顶不匹配
        } else {
            stack.push(c);                        // 遇到左括号,压栈等待配对
        }
    }
    return stack.length === 0;                    // 栈必须清空才合法
}

