solution.typescript:
function decodeString(s: string): string {
    const numStack: number[] = [], strStack: string[] = [];  // 分别存重复次数、括号外已拼好的串
    let cur = "", num = 0;                        // cur:当前层拼接中的串;num:当前重复数
    for (const c of s) {
        if (c >= '0' && c <= '9') {
            num = num * 10 + (c.charCodeAt(0) - 48);   // 数字可能多位,累积
        } else if (c === '[') {
            numStack.push(num);                   // 存档:进入新一层前,把外层状态压栈
            strStack.push(cur);
            num = 0; cur = "";                    // 清空,开始处理括号内部
        } else if (c === ']') {
            cur = strStack.pop()! + cur.repeat(numStack.pop()!);   // 内层结果重复若干次拼回外层
        } else {
            cur += c;                             // 普通字母,直接接到当前串
        }
    }
    return cur;
}

