function detectCycle(head: ListNode | null): ListNode | null {
    let slow = head, fast = head;
    while (fast && fast.next) {                    // 快指针每次两步,先确保不越界
        slow = slow!.next;                         // 慢:一步
        fast = fast.next.next;                     // 快:两步
        if (slow === fast) {                       // 相遇 -> 有环
            let p = head;                          // 一个指针回到起点
            while (p !== slow) {                   // 两指针同速走,相遇处即环入口
                p = p!.next; slow = slow!.next;
            }
            return p;
        }
    }
    return null;                                   // 快指针到头,无环
}

