function mergeTwoLists(a: ListNode | null, b: ListNode | null): ListNode | null {
    const dummy = new ListNode();                  // dummy 虚拟头
    let tail = dummy;                              // tail 始终指向结果末尾
    while (a && b) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }   // 挑较小的头节点接上
        else { tail.next = b; b = b.next; }
        tail = tail.next;                          // 结果末尾后移
    }
    tail.next = a ?? b;                            // 谁没走完,把剩余整段直接接上
    return dummy.next;                             // dummy.next 才是真正的头
}

