function removeNthFromEnd(head: ListNode | null, n: number): ListNode | null {
    const dummy = new ListNode(0, head);           // dummy 处理"删的是头节点"的边界
    let fast = dummy, slow = dummy;
    for (let i = 0; i < n; i++) fast = fast.next;  // 快指针先走 N 步,拉开固定间距
    while (fast.next) {                            // 两指针同步走,直到快指针到末尾
        fast = fast.next; slow = slow.next;
    }
    slow.next = slow.next.next;                    // slow 正好在待删点前一个,跳过它
    return dummy.next;
}

