function addTwoNumbers(a: ListNode | null, b: ListNode | null): ListNode | null {
    const dummy = new ListNode();
    let tail = dummy;
    let carry = 0;                                 // 进位
    while (a || b || carry) {                      // 任一还有位、或还有进位,就继续
        const s = carry + (a ? a.val : 0) + (b ? b.val : 0);  // 本位求和
        carry = Math.floor(s / 10);                // 商是进位
        tail.next = new ListNode(s % 10);          // 余是本位数字,接上新节点
        tail = tail.next;
        a = a ? a.next : null;                      // 两条链各自后移(短的用 null 补 0)
        b = b ? b.next : null;
    }
    return dummy.next;
}

