solution.typescript:
class LRUCache {
    private cap: number;
    private cache = new Map<number, number>();     // Map 天然维护插入/使用顺序

    constructor(capacity: number) {
        this.cap = capacity;
    }

    get(key: number): number {
        if (!this.cache.has(key)) return -1;
        const v = this.cache.get(key)!;
        this.cache.delete(key);
        this.cache.set(key, v);                    // 命中 -> 挪到末尾,标记为"最近使用"
        return v;
    }

    put(key: number, value: number): void {
        if (this.cache.has(key)) this.cache.delete(key);   // 已存在,先删再插到末尾
        this.cache.set(key, value);
        if (this.cache.size > this.cap) {
            const oldest = this.cache.keys().next().value;  // 最前面的即最久没用的
            this.cache.delete(oldest);
        }
    }
}

