solution.typescript:
function dailyTemperatures(temps: number[]): number[] {
    const res = new Array(temps.length).fill(0);
    const stack: number[] = [];                    // 存下标,对应温度单调递减
    for (let i = 0; i < temps.length; i++) {
        while (stack.length && temps[stack[stack.length - 1]] < temps[i]) {  // 今天比栈顶那天暖
            const j = stack.pop()!;                // 栈顶那天等到了
            res[j] = i - j;                        // 答案 = 天数差
        }
        stack.push(i);                             // 今天自己也入栈等待
    }
    return res;
}

