class MinStack {
    private stack: number[] = [];
    private mins: number[] = [];                   // 辅助栈:mins[i] = 主栈前 i 个的最小值

    push(x: number): void {
        this.stack.push(x);
        const min = this.mins.length ? Math.min(x, this.mins[this.mins.length - 1]) : x;
        this.mins.push(min);                       // 压入"当前最小值"
    }

    pop(): void {
        this.stack.pop(); this.mins.pop();         // 两栈同步弹出
    }

    top(): number {
        return this.stack[this.stack.length - 1];
    }

    getMin(): number {
        return this.mins[this.mins.length - 1];    // 栈顶即当前最小值,O(1)
    }
}

