function inorderTraversal(root: TreeNode | null): number[] {
    const res: number[] = [];
    const dfs = (node: TreeNode | null): void => {
        if (!node) return;                         // 空节点直接返回(递归出口)
        dfs(node.left);                            // 先遍历左子树
        res.push(node.val);                        // 再访问自己(这句的位置决定前/中/后序)
        dfs(node.right);                           // 最后遍历右子树
    };
    dfs(root);
    return res;
}

