function levelOrder(root: TreeNode | null): number[][] {
    if (!root) return [];
    const res: number[][] = [];
    let q: TreeNode[] = [root];
    while (q.length) {
        const level: number[] = [];
        const next: TreeNode[] = [];
        for (const node of q) {                    // 关键:锁定本层节点,只处理这些
            level.push(node.val);
            if (node.left) next.push(node.left);   // 孩子入队,留给下一层
            if (node.right) next.push(node.right);
        }
        res.push(level);                           // 一层收集完
        q = next;
    }
    return res;
}

