solution.typescript:
function lowestCommonAncestor(root: TreeNode | null, p: TreeNode, q: TreeNode): TreeNode | null {
    if (!root || root === p || root === q) return root;   // 撞到目标或空,直接上报
    const left = lowestCommonAncestor(root.left, p, q);   // 左子树找的结果
    const right = lowestCommonAncestor(root.right, p, q); // 右子树找的结果
    if (left && right) return root;                // 两侧各找到一个 -> 当前节点是分岔口(LCA)
    return left ?? right;                          // 只有一侧非空 -> 答案在那侧
}

