function diameterOfBinaryTree(root: TreeNode | null): number {
    let best = 0;
    const depth = (node: TreeNode | null): number => {    // 返回以 node 为根的树高
        if (!node) return 0;
        const l = depth(node.left), r = depth(node.right);
        best = Math.max(best, l + r);              // 经过当前节点的路径长 = 左深 + 右深
        return 1 + Math.max(l, r);                 // 向上返回:只能带更深的一条边
    };
    depth(root);
    return best;
}

