function maxPathSum(root: TreeNode | null): number {
    let best = -Infinity;
    const gain = (node: TreeNode | null): number => {     // 返回从 node 向下走一条边的最大贡献
        if (!node) return 0;
        const l = Math.max(gain(node.left), 0);    // 子树贡献为负则舍弃(取 0)
        const r = Math.max(gain(node.right), 0);
        best = Math.max(best, node.val + l + r);   // 更新答案:可拼上左右两条边
        return node.val + Math.max(l, r);          // 向上返回:只能选一条边(路径不分叉)
    };
    gain(root);
    return best;
}

