function buildTree(preorder: number[], inorder: number[]): TreeNode | null {
    const idx = new Map<number, number>();         // 中序值 -> 下标,O(1) 定位根
    inorder.forEach((v, i) => idx.set(v, i));
    let pre = 0;                                   // 前序游标,按序吐出每个根
    const build = (lo: number, hi: number): TreeNode | null => {   // 用中序区间 [lo, hi] 建子树
        if (lo > hi) return null;                  // 区间为空
        const val = preorder[pre++];               // 前序的下一个就是当前子树的根
        const root = new TreeNode(val);
        const mid = idx.get(val)!;                 // 根在中序里的位置,切分左右
        root.left = build(lo, mid - 1);            // 必须先建左子树(前序是根-左-右)
        root.right = build(mid + 1, hi);
        return root;
    };
    return build(0, inorder.length - 1);
