function isValidBST(root: TreeNode | null): boolean {
    const valid = (node: TreeNode | null, low: number, high: number): boolean => {  // 值须严格落在 (low, high)
        if (!node) return true;
        if (!(low < node.val && node.val < high)) return false;   // 越界即非法
        // 往左:上界收紧为当前值;往右:下界抬高为当前值
        return valid(node.left, low, node.val) && valid(node.right, node.val, high);
    };
    return valid(root, -Infinity, Infinity);
}

