function rightSideView(root: TreeNode | null): number[] {
    if (!root) return [];
    const res: number[] = [];
    let q: TreeNode[] = [root];
    while (q.length) {
        const next: TreeNode[] = [];
        for (let i = 0; i < q.length; i++) {
            const node = q[i];
            if (i === q.length - 1) res.push(node.val);   // 本层最后一个 = 右视图看到的
            if (node.left) next.push(node.left);
            if (node.right) next.push(node.right);
        }
        q = next;
    }
    return res;
}

