    let l = 0, r = nums.length - 1;                // 闭区间 [l, r]
    while (l <= r) {                               // 区间非空就继续
        const mid = (l + r) >> 1;
        if (nums[mid] === target) return mid;
        else if (nums[mid] < target) l = mid + 1;  // 中间偏小,去右半找
        else r = mid - 1;                          // 中间偏大,去左半找
    }
    return -1;                                     // 没找到
}

