function searchRange(nums: number[], target: number): number[] {
    const bound = (isLeft: boolean): number => {   // isLeft=true 找左边界,否则找右边界
        let l = 0, r = nums.length - 1, res = -1;
        while (l <= r) {
            const mid = (l + r) >> 1;
            // 找左边界时命中也往左挤;找右边界时命中也往右挤
            if (nums[mid] < target || (!isLeft && nums[mid] === target)) l = mid + 1;
            else r = mid - 1;
            if (nums[mid] === target) res = mid;   // 记录最近一次命中
        }
        return res;
    };
    return [bound(true), bound(false)];
}

