solution.typescript:
function permute(nums: number[]): number[][] {
    const res: number[][] = [];
    const bt = (path: number[], rest: number[]): void => {   // path:已选;rest:还能选的
        if (rest.length === 0) {                   // 没得选了 -> 一个完整排列
            res.push([...path]);
            return;
        }
        for (let i = 0; i < rest.length; i++) {
            // 选 rest[i] 进路径,把它从候选里去掉,递归
            bt([...path, rest[i]], [...rest.slice(0, i), ...rest.slice(i + 1)]);
        }
    };
    bt([], nums);
    return res;
}

