solution.typescript:
function combinationSum(candidates: number[], target: number): number[][] {
    const res: number[][] = [];
    const bt = (start: number, path: number[], remain: number): void => {   // remain:还差多少凑到 target
        if (remain === 0) {                        // 凑齐了
            res.push([...path]);
            return;
        }
        for (let i = start; i < candidates.length; i++) {
            if (candidates[i] <= remain) {         // 剪枝:比剩余还大就没必要
                // 传 i(不是 i+1):同一个数可以重复选
                bt(i, [...path, candidates[i]], remain - candidates[i]);
            }
        }
    };
    bt(0, [], target);
    return res;
}

