solution.typescript:
function generateParenthesis(n: number): string[] {
    const res: string[] = [];
    const bt = (s: string, left: number, right: number): void => {   // left/right:已用的左/右括号数
        if (s.length === 2 * n) {                  // 长度够了 -> 一个合法组合
            res.push(s);
            return;
        }
        if (left < n) bt(s + '(', left + 1, right);   // 左括号没用完,可以加左
        if (right < left) bt(s + ')', left, right + 1);   // 右括号数不能超过左括号数
    };
    bt('', 0, 0);
    return res;
}

