solution.typescript:
function exist(board: string[][], word: string): boolean {
    const rows = board.length, cols = board[0].length;
    const dfs = (r: number, c: number, i: number): boolean => {   // i:当前要匹配 word 的第几个字符
        if (i === word.length) return true;        // 全部匹配完
        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] !== word[i]) {
            return false;                          // 越界 或 字符不匹配
        }
        const tmp = board[r][c];
        board[r][c] = '#';                         // 标记已访问,防止走回头路
        const found = dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) ||
                      dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1);   // 四方向探路
        board[r][c] = tmp;                         // 回溯:恢复格子,供别的路径使用
        return found;
    };
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (dfs(r, c, 0)) return true;
    return false;
}

