solution.typescript:
function rob(nums: number[]): number {
    let prev = 0, cur = 0;                         // prev:偷到前前家的最大值;cur:偷到前一家的
    for (const x of nums) {
        // 不偷这家(cur) vs 偷这家(prev + x),取较大
        [prev, cur] = [cur, Math.max(cur, prev + x)];
    }
    return cur;
}

