solution.typescript:
function lengthOfLIS(nums: number[]): number {
    const tails: number[] = [];                    // tails[i] = 长度为 i+1 的递增子序列的最小结尾
    for (const x of nums) {
        let lo = 0, hi = tails.length;             // 二分找第一个 >= x 的位置
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        if (lo === tails.length) tails.push(x);    // x 比所有结尾都大 -> 序列变长
        else tails[lo] = x;                        // 否则替换,让该长度的结尾更小
    }
    return tails.length;                           // 长度即答案
}

