solution.typescript:
function coinChange(coins: number[], amount: number): number {
    const dp = new Array(amount + 1).fill(Infinity);   // dp[a] = 凑出金额 a 的最少硬币数
    dp[0] = 0;                                     // 凑 0 元需要 0 枚
    for (const c of coins) {
        for (let a = c; a <= amount; a++) {        // 正序:完全背包,硬币可重复用
            dp[a] = Math.min(dp[a], dp[a - c] + 1);// 用一枚 c,或不用,取更少
        }
    }
    return dp[amount] === Infinity ? -1 : dp[amount];   // 凑不出返回 -1
}

