solution.typescript:
function longestCommonSubsequence(a: string, b: string): number {
    const m = a.length, n = b.length;
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));   // dp[i][j]:a 前 i、b 前 j 的 LCS 长
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (a[i - 1] === b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;   // 末字符相同,走对角线 + 1
            else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);        // 不同,丢掉一个串末字符取较优
        }
    }
    return dp[m][n];
}

