    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (a[i - 1] === b[j - 1]) dp[i][j] = dp[i - 1][j - 1];   // 末字符相同,不操作
            else dp[i][j] = 1 + Math.min(dp[i - 1][j],   // 删 a 的末字符
                                         dp[i][j - 1],   // 增一个字符
                                         dp[i - 1][j - 1]);   // 改末字符
        }
    }
    return dp[m][n];
}

