function uniquePaths(m: number, n: number): number {
    const dp = new Array(n).fill(1);               // 滚动数组:第一行都是 1(只能一直往右)
    for (let i = 1; i < m; i++) {                  // 逐行往下
        for (let j = 1; j < n; j++) {
            dp[j] += dp[j - 1];                    // 上方(旧 dp[j]) + 左方(dp[j-1])
        }
    }
    return dp[n - 1];
}

