function maxProfit(prices: number[]): number {
    let minPrice = Infinity;                       // 到目前为止见过的最低价(最佳买入点)
    let best = 0;
    for (const p of prices) {
        minPrice = Math.min(minPrice, p);          // 刷新历史最低价
        best = Math.max(best, p - minPrice);       // 今天卖出的利润 vs 历史最好
    }
    return best;
}

