solution.typescript:
function canPartition(nums: number[]): boolean {
    const total = nums.reduce((a, b) => a + b, 0);
    if (total % 2 !== 0) return false;             // 总和为奇数,不可能平分
    const target = total / 2;
    const dp = new Array(target + 1).fill(false);  // dp[j]:能否凑出和 j
    dp[0] = true;                                  // 凑 0 恒可行(什么都不选)
    for (const x of nums) {
        for (let j = target; j >= x; j--) {        // 倒序:0/1 背包,每个数只用一次
            dp[j] = dp[j] || dp[j - x];            // 不选 x,或选 x(从 j-x 转移)
        }
    }
    return dp[target];
}

