function maximalSquare(matrix: string[][]): number {
    if (!matrix.length) return 0;
    const m = matrix.length, n = matrix[0].length;
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));   // dp[i][j]:以 (i-1,j-1) 为右下角的最大边长
    let best = 0;
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (matrix[i - 1][j - 1] === '1') {
                // 左、上、左上三者最短的 + 1(木桶效应)
                dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;
                best = Math.max(best, dp[i][j]);
            }
        }
    }
    return best * best;                            // 答案是面积 = 边长²
}

