function jump(nums: number[]): number {
    let jumps = 0, end = 0, farthest = 0;          // end:当前这一跳的边界;farthest:能探到的最远
    for (let i = 0; i < nums.length - 1; i++) {    // 到倒数第二个即可
        farthest = Math.max(farthest, i + nums[i]);
        if (i === end) {                           // 走到当前跳的边界,必须再跳一次
            jumps++;
            end = farthest;                        // 边界更新为这一跳能到的最远处
        }
    }
    return jumps;
}

