function numIslands(grid: string[][]): number {
    if (!grid.length) return 0;
    const rows = grid.length, cols = grid[0].length;
    const dfs = (r: number, c: number): void => {  // 把 (r,c) 所在的整片陆地淹掉
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] !== '1') return;   // 越界或不是陆地
        grid[r][c] = '0';                          // 淹没,标记已访问
        dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1);   // 四方向扩散
    };
    let count = 0;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === '1') {              // 发现新岛
                count++;
                dfs(r, c);                         // 计数并淹掉整座
            }
        }
    }
    return count;
}

