function orangesRotting(grid: number[][]): number {
    const rows = grid.length, cols = grid[0].length;
    let q: [number, number][] = [];
    let fresh = 0;
    for (let r = 0; r < rows; r++) {               // 先扫一遍:烂橘子入队,统计新鲜橘子
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === 2) q.push([r, c]);  // 所有烂橘子当作第 0 层起点
            else if (grid[r][c] === 1) fresh++;
        }
    }
    let minutes = 0;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    while (q.length && fresh) {                     // 还有橘子在扩散且还有新鲜的
        minutes++;                                 // 扩散一层 = 过一分钟
        const next: [number, number][] = [];
        for (const [r, c] of q) {                  // 只处理当前这一层
            for (const [dr, dc] of dirs) {         // 四方向
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === 1) {
                    grid[nr][nc] = 2; fresh--; next.push([nr, nc]);   // 传染
                }
            }
        }
        q = next;
    }
    return fresh === 0 ? minutes : -1;             // 还有新鲜的说明烂不到,返回 -1
}

