solution.typescript:
function canFinish(numCourses: number, prerequisites: number[][]): boolean {
    const graph: number[][] = Array.from({ length: numCourses }, () => []);   // pre -> [依赖它的课程]
    const indeg = new Array(numCourses).fill(0);   // 每门课的入度(有几门前置)
    for (const [course, pre] of prerequisites) {
        graph[pre].push(course);                   // 先修 pre 才能修 course
        indeg[course]++;
    }
    let q: number[] = [];
    for (let i = 0; i < numCourses; i++) if (indeg[i] === 0) q.push(i);   // 无前置的先入队
    let done = 0;
    while (q.length) {
        const node = q.shift()!;
        done++;                                    // 修掉一门
        for (const nxt of graph[node]) {           // 解锁它的后继
            if (--indeg[nxt] === 0) q.push(nxt);   // 前置全修完,可以修了
        }
    }
    return done === numCourses;                    // 全修完 = 无环
}

