solution.typescript:
function findKthLargest(nums: number[], k: number): number {
    // 小顶堆:堆顶始终是当前 k 个里最小的
    const heap: number[] = [];
    const up = (i: number) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
        }
    };
    const down = (i: number) => {
        const n = heap.length;
        while (true) {
            let s = i, l = 2 * i + 1, r = 2 * i + 2;
            if (l < n && heap[l] < heap[s]) s = l;
            if (r < n && heap[r] < heap[s]) s = r;
            if (s === i) break;
            [heap[s], heap[i]] = [heap[i], heap[s]]; i = s;
        }
    };
    for (const x of nums) {
        if (heap.length < k) { heap.push(x); up(heap.length - 1); }
        else if (x > heap[0]) { heap[0] = x; down(0); }   // 新数比擂台上最弱的还强,替换
    }
    return heap[0];                                // 堆顶 = 最大 k 个里最小的 = 第 k 大
}

