solution.typescript:
function topKFrequent(nums: number[], k: number): number[] {
    const count = new Map<number, number>();       // 统计每个数的出现次数
    for (const x of nums) count.set(x, (count.get(x) ?? 0) + 1);
    // 按频率降序排序,取前 k 个 key
    return [...count.entries()]
        .sort((a, b) => b[1] - a[1])
        .slice(0, k)
        .map(e => e[0]);
}

