solution.typescript:
function mergeKLists(lists: Array<ListNode | null>): ListNode | null {
    // 用小顶堆存各链表当前头节点,每次取最小
    const heap: ListNode[] = [];
    const up = (i: number) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p].val <= heap[i].val) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
        }
    };
    const down = (i: number) => {
        const n = heap.length;
        while (true) {
            let s = i, l = 2 * i + 1, r = 2 * i + 2;
            if (l < n && heap[l].val < heap[s].val) s = l;
            if (r < n && heap[r].val < heap[s].val) s = r;
            if (s === i) break;
            [heap[s], heap[i]] = [heap[i], heap[s]]; i = s;
        }
    };
    const push = (node: ListNode) => { heap.push(node); up(heap.length - 1); };
    const pop = (): ListNode => {
        const top = heap[0], last = heap.pop()!;
        if (heap.length) { heap[0] = last; down(0); }
        return top;
    };
    for (const node of lists) if (node) push(node);
    const dummy = new ListNode();
    let tail = dummy;
    while (heap.length) {
        const node = pop();                        // 弹出所有链头里最小的
        tail.next = node; tail = node;             // 接到结果末尾
        if (node.next) push(node.next);            // 补上它的后继
    }
    return dummy.next;
}

